/**
 * The sandbox engine: Anthropic's sandbox-runtime (`@anthropic-ai/sandbox-runtime`, pinned in package.json). Every
 * macOS Seatbelt profile and every Linux bubblewrap + seccomp invocation a fenced launch runs under is generated by
 * its own code, per launch, from a small static config (read denies with exact re-allows, write roots with denies
 * inside them, mach services, the run's proxy). Toolroll adds only what that config says (agent-fence.ts srtTermsOf),
 * plus, on macOS, a few static rules of its own appended to the end of the profile (seatbeltRulesFor: a terminal of the
 * launch's own and no other, no keystrokes pushed into a terminal, a check's Chromium service, the keychain's services
 * only for builds); the rest of the rules, their baseline and their limits are the runtime's.
 *
 * macOS: its profile builder runs in this process (it is synchronous), with this process's working folder set to the
 * launch's for the call, because the runtime anchors its mandatory write denies (.git/hooks, .vscode, shell profiles)
 * at the working folder. Linux: its builder is asynchronous, anchored at the working folder too, and leaves mount
 * points to clean up after the command, so each Linux launch runs through a small helper process
 * (sandbox-launch.ts) that changes into the launch's folder, asks the runtime for the command, runs it and cleans up.
 */
import { spawnSync } from "node:child_process";
import { accessSync, constants as fsConstants, existsSync, mkdirSync, readFileSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { delimiter, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { wrapCommandWithSandboxMacOS } from "@anthropic-ai/sandbox-runtime/dist/sandbox/macos-sandbox-utils.js";
import { checkLinuxDependencies, getLinuxDependencyStatus } from "@anthropic-ai/sandbox-runtime/dist/sandbox/linux-sandbox-utils.js";
import type { FsReadRestrictionConfig, FsWriteRestrictionConfig } from "@anthropic-ai/sandbox-runtime";
import { linuxSandboxTools, sandboxToolExclusions, seccompHelperRepair, type LinuxSandboxTools, type LinuxSandboxToolsVerdict, type ToolExclusions } from "./sandbox-tools.js";
import { trustRepairLines } from "./trust-repair.js";
import { installLine, packageSystem, type PackageSystem } from "./linux-packages.js";

const require = createRequire(import.meta.url);

/** The engine and its exact version, as the console and the words say it. */
export const SANDBOX_RUNTIME: { name: string; version: string } = (() => {
  const name = "@anthropic-ai/sandbox-runtime";
  try {
    const manifest = JSON.parse(readFileSync(join(dirname(require.resolve(name)), "..", "package.json"), "utf8")) as { version?: unknown };
    return { name, version: typeof manifest.version === "string" ? manifest.version : "unknown" };
  } catch {
    return { name, version: "unknown" };
  }
})();

/** "Anthropic's sandbox-runtime 0.0.79": how every surface names the engine. */
export const sandboxRuntimeWords = (): string => `Anthropic's sandbox-runtime ${SANDBOX_RUNTIME.version}`;

/**
 * One launch's sandbox, as the runtime's own config: what it may not read (and the exact paths read again inside
 * those), where it may write (and what stays unwritable there), the extra macOS services it may look up, and its
 * network (open, or only through this run's proxy; a tool broker rides the runtime's second relay).
 */
export type SrtTerms = {
  readConfig: FsReadRestrictionConfig;
  writeConfig: FsWriteRestrictionConfig;
  allowMachLookup: string[];
  /** macOS: the launch may reach the keychain's services (securityd). Only a build's agent: every other launch is
   * denied them (SEATBELT_NO_KEYCHAIN). */
  keychain?: boolean;
  /** macOS: a project check's launch, whose Chromium may register and reach its own service (SEATBELT_CHROMIUM). */
  browser?: boolean;
  network: { kind: "open" } | { kind: "proxy"; httpPort: number; socksPort?: number; token?: string; localServices: boolean; unixSockets: string[] };
};

const SANDBOX_EXEC = "/usr/bin/sandbox-exec";
/** A deny-by-default profile, as the runtime's are: inside another sandbox one can't be applied (an allow-by-default one
 * still can, so it proves nothing). */
export const SEATBELT_PROBE = "(version 1)(deny default)(allow process-exec)(allow process-fork)(allow file-read*)(allow sysctl-read)(allow mach-lookup)";

/**
 * Why the runtime can't sandbox here, as a kind: a program missing, one that fails its trust check, a processor the
 * runtime ships no helper for, a probe that couldn't start or didn't finish, or a sandbox the system denied. A denial
 * names its cause only with evidence this machine shows (a readable setting); otherwise the cause is unknown. `detail`:
 * the probe's own words, bounded.
 */
export type SandboxDiagnosis = { ok: true } | { ok: false; kind: "unsupported-platform" | "missing-tool" | "trust" | "unsupported-arch" | "launch-error" | "timeout" | "sandbox-denied"; why: string; detail?: string; cause?: SandboxDenialCause | null };
/** A cause shown by a setting this machine lets Toolroll read, with what an administrator can do about it. */
export type SandboxDenialCause = { words: string; fix: string };

/** What the probe reads besides running bubblewrap (a test's stand-in). */
export type SandboxIo = { read?: (file: string) => string; exists?: (file: string) => boolean };

const DETAIL_MAX = 300;
/** A probe's output, kept short and on one line (it may carry anything: never more than this). */
const bounded = (text: string): string => text.replace(/[\u0000-\u001f\u007f]+/g, " ").trim().slice(0, DETAIL_MAX);

/** Why the runtime can't sandbox here, or null when it can (checked before every launch; nothing runs bare). */
export function sandboxRuntimeProblem(platform: NodeJS.Platform = process.platform): string | null {
  const diagnosis = sandboxRuntimeDiagnosis(platform);
  return diagnosis.ok ? null : diagnosis.why;
}

/** sandboxRuntimeProblem, as a kind with its evidence (see SandboxDiagnosis). */
export function sandboxRuntimeDiagnosis(platform: NodeJS.Platform = process.platform, io: SandboxIo = {}): SandboxDiagnosis {
  if (platform === "darwin") {
    if (!existsSync(SANDBOX_EXEC)) return { ok: false, kind: "missing-tool", why: "this Mac has no sandbox-exec" };
    const probe = spawnSync(SANDBOX_EXEC, ["-p", SEATBELT_PROBE, "/usr/bin/true"], { timeout: 5_000, stdio: ["ignore", "ignore", "pipe"], encoding: "utf8" });
    return probe.status === 0 ? { ok: true } : { ok: false, kind: "sandbox-denied", why: "sandbox-exec can't start a sandbox here (is this already inside one?)", detail: bounded(probe.stderr ?? "") };
  }
  if (platform === "linux") {
    // The programs it needs, named with the line that installs them (LINUX_SANDBOX_TOOLS), before anything else.
    const missing = missingLinuxSandboxTools();
    if (missing.length > 0) return { ok: false, kind: "missing-tool", why: `${toolWords(missing)} ${missing.length === 1 ? "is" : "are"} not installed (${linuxSandboxInstallLine(missing)})` };
    // Each program the sandbox runs, by a path Toolroll trusts (never a PATH lookup): none, and no sandbox starts.
    const resolved = linuxSandboxTools();
    if (!resolved.ok) {
      const kind = /isn't available for this processor/.test(resolved.why) ? "unsupported-arch" : /has no copy owned by root/.test(resolved.why) ? "missing-tool" : "trust";
      return { ok: false, kind, why: resolved.why };
    }
    const { tools } = resolved;
    const paths = { bwrapPath: tools.bwrap.real, socatPath: tools.socat.real, seccompConfig: { applyPath: tools.seccomp.real } };
    const checked = checkLinuxDependencies(paths);
    if (checked.errors.length > 0) return { ok: false, kind: "launch-error", why: checked.errors.join("; ") };
    if (!getLinuxDependencyStatus(paths).hasSeccompApply) return { ok: false, kind: "unsupported-arch", why: "the sandbox runtime's seccomp helper isn't available for this processor" };
    // The runtime finds nested protected names (a subfolder's .git/hooks, .vscode, shell profiles) with ripgrep.
    if (spawnSync(tools.rg.real, ["--version"], { timeout: 5_000, stdio: "ignore" }).status !== 0) return { ok: false, kind: "launch-error", why: `ripgrep (${tools.rg.real}) doesn't run` };
    // The probe runs as this user, with Toolroll's own checked bubblewrap: what a launch needs (a user and pid namespace).
    const probe = spawnSync(tools.bwrap.real, ["--ro-bind", "/", "/", "--unshare-pid", "--unshare-user", "--proc", "/proc", "--new-session", "--", "true"], { timeout: 5_000, stdio: ["ignore", "ignore", "pipe"], encoding: "utf8", maxBuffer: 64 * 1024 });
    if (probe.status === 0) return { ok: true };
    const detail = bounded(probe.stderr ?? "");
    const code = (probe.error as NodeJS.ErrnoException | undefined)?.code;
    if (code === "ETIMEDOUT") return { ok: false, kind: "timeout", why: "bubblewrap didn't finish starting a sandbox in time", detail };
    if (probe.error !== undefined) return { ok: false, kind: "launch-error", why: `bubblewrap (${tools.bwrap.real}) couldn't be started (${code ?? "error"})`, detail };
    const cause = userNamespaceCause(io);
    return { ok: false, kind: "sandbox-denied", cause, detail,
      why: cause === null ? "this system denied the user namespace the sandbox needs; the cause isn't visible from inside this machine" : `this system denied the user namespace the sandbox needs: ${cause.words}` };
  }
  return { ok: false, kind: "unsupported-platform", why: `the sandbox runtime has no sandbox for ${platform}` };
}

/**
 * Why this Linux denies an unprivileged user namespace, only from a setting it lets this user read (null otherwise:
 * EPERM, a container marker or a seccomp filter alone can't tell seccomp from AppArmor from anything else).
 */
export function userNamespaceCause(io: SandboxIo = {}): SandboxDenialCause | null {
  const read = (file: string): string | null => { try { return (io.read ?? (one => readFileSync(one, "utf8")))(file).trim(); } catch { return null; } };
  if (read("/proc/sys/kernel/apparmor_restrict_unprivileged_userns") === "1") return {
    words: "AppArmor restricts unprivileged user namespaces on this computer (kernel.apparmor_restrict_unprivileged_userns = 1)",
    fix: "An administrator can give bubblewrap an AppArmor profile that allows user namespaces (a profile for /usr/bin/bwrap with `userns,`), rather than lifting the restriction for every program.",
  };
  if (read("/proc/sys/kernel/unprivileged_userns_clone") === "0") return {
    words: "unprivileged user namespaces are turned off (kernel.unprivileged_userns_clone = 0)",
    fix: "An administrator can turn them on: `sudo sysctl -w kernel.unprivileged_userns_clone=1`, kept in a file under /etc/sysctl.d/.",
  };
  if (read("/proc/sys/user/max_user_namespaces") === "0") return {
    words: "user namespaces are turned off (user.max_user_namespaces = 0)",
    fix: "An administrator can allow them: `sudo sysctl -w user.max_user_namespaces=15000`, kept in a file under /etc/sysctl.d/.",
  };
  return null;
}

/** Whether this looks like a container (a marker file, or a seccomp filter on this process): only to word the advice. */
function looksContained(io: SandboxIo): boolean {
  const exists = io.exists ?? existsSync;
  if (exists("/.dockerenv") || exists("/run/.containerenv")) return true;
  try { return /^Seccomp:\s*2$/m.test((io.read ?? (one => readFileSync(one, "utf8")))("/proc/self/status")); } catch { return false; }
}

/**
 * What a person can do when the sandbox can't start, as lines (none for a missing program: its install line says it,
 * and a trust failure: its repair does). An administrator's targeted policy first; weakening a container's own
 * protection only as the last, said so; then the existing opt-in, which runs agents without OS confinement and stays an
 * instance operator's logged choice (never automatic, refused in local mode).
 */
export function sandboxRemedyLines(diagnosis: SandboxDiagnosis, io: SandboxIo = {}): string[] {
  if (diagnosis.ok || diagnosis.kind === "missing-tool" || diagnosis.kind === "trust") return [];
  const lines: string[] = [];
  if (diagnosis.kind === "sandbox-denied" && diagnosis.cause != null) lines.push(diagnosis.cause.fix);
  else if (diagnosis.kind === "sandbox-denied" && looksContained(io)) {
    lines.push("In a container (Docker, a devcontainer, Codespaces) its seccomp or AppArmor profile usually denies user namespaces: an administrator can allow them with a profile for this container. Starting it with `--security-opt seccomp=unconfined --security-opt apparmor=unconfined` also works, but weakens the container's own protection.");
  }
  if (diagnosis.kind === "unsupported-arch") lines.push("This processor has no sandbox helper: Toolroll's sandbox runs on 64-bit Intel/AMD (x64) and ARM (arm64) Linux.");
  lines.push(UNCONFINED_OPT_IN);
  return lines;
}

/** The existing opt-in, as every surface names it: an instance operator's choice, never automatic. */
export const UNCONFINED_OPT_IN = "Or an instance operator can let agents run without OS confinement: `toolroll config unconfined-agents allow` (their password, logged; refused while Toolroll runs without a password).";

/** The lines after "the sandbox isn't available here": a trust failure's exact repair, else what the probe said and the
 * remedies (sandboxRemedyLines). None when it works or a program is missing (its install line is in the reason). */
export function sandboxAdviceLines(diagnosis: SandboxDiagnosis, io: SandboxIo = {}): string[] {
  if (diagnosis.ok || diagnosis.kind === "missing-tool") return [];
  if (diagnosis.kind === "trust") return sandboxRuntimeRepair();
  return [...diagnosis.detail === undefined || diagnosis.detail === "" ? [] : [`(${diagnosis.kind === "sandbox-denied" || diagnosis.kind === "timeout" ? "bubblewrap" : "it"} said: ${diagnosis.detail})`], ...sandboxRemedyLines(diagnosis, io)];
}

/**
 * The refusal when nothing can confine `what` ("an agent", "the build's commands"): why (the diagnosis, never "install"
 * when the programs are installed), what fixes it, and the opt-in. Read now, on the refusal's own path.
 */
export function noConfinementWords(what: string, done: string, diagnosis: SandboxDiagnosis = sandboxRuntimeDiagnosis()): string {
  const why = diagnosis.ok ? "its sandbox isn't available to this run" : diagnosis.why;
  const fix = diagnosis.ok || diagnosis.kind === "missing-tool" ? "" : diagnosis.kind === "trust" ? " `toolroll doctor` prints the exact fix." : diagnosis.kind === "sandbox-denied" && diagnosis.cause != null ? ` ${diagnosis.cause.fix}` : "";
  return `This machine can't confine ${what}, so ${done}: ${why}.${fix} ${UNCONFINED_OPT_IN}`;
}

/** Linux: when the sandbox's own seccomp helper fails its trust check, what fails and the exact repair, as lines
 * (sandbox-tools.ts seccompHelperRepair); none otherwise. The check is unchanged and runs again at every launch. */
export function sandboxRuntimeRepair(platform: NodeJS.Platform = process.platform): string[] {
  if (platform !== "linux") return [];
  const repair = seccompHelperRepair();
  return repair === null ? [] : trustRepairLines(repair);
}

/**
 * The programs the Linux sandbox needs on PATH, each with the package that installs it (linux-packages.ts names it per
 * manager). bubblewrap and socat are what the runtime's own check (checkLinuxDependencies) requires; ripgrep is how it
 * finds nested protected names; bash and which are what it runs commands with and looks the shell up by
 * (sandbox-tools.ts checks every one). The one list: every message, install.sh's tip and docs/guide/linux.md name
 * exactly these (sandbox-runtime.test.ts holds them to it).
 */
export const LINUX_SANDBOX_TOOLS: readonly { command: string; package: string }[] = [
  { command: "bwrap", package: "bubblewrap" },
  { command: "socat", package: "socat" },
  { command: "rg", package: "ripgrep" },
  { command: "bash", package: "bash" },
  { command: "which", package: "which" },
];

/** "bubblewrap, socat and ripgrep": packages, in words. */
function toolWords(packages: readonly string[]): string {
  return packages.length <= 1 ? packages.join("") : `${packages.slice(0, -1).join(", ")} and ${packages.at(-1)}`;
}

/** The packages of LINUX_SANDBOX_TOOLS whose program isn't on this PATH (an executable file in one of its folders). */
export function missingLinuxSandboxTools(path: string = process.env["PATH"] ?? ""): string[] {
  const folders = path.split(delimiter).filter(folder => folder !== "");
  const found = (command: string) => folders.some(folder => {
    try { accessSync(join(folder, command), fsConstants.X_OK); return statSync(join(folder, command)).isFile(); } catch { return false; }
  });
  return LINUX_SANDBOX_TOOLS.filter(tool => !found(tool.command)).map(tool => tool.package);
}

/** The line that installs these packages with this computer's package manager (linux-packages.ts: apt with its lists
 * refreshed first, dnf, zypper, pacman or apk; sudo only when not root; every manager's line when none is found). */
export function linuxSandboxInstallLine(packages: readonly string[] = LINUX_SANDBOX_TOOLS.map(tool => tool.package), system: PackageSystem = packageSystem()): string {
  return installLine(packages, system);
}

/** "bubblewrap, socat and ripgrep": what every "Install …" sentence names. */
export const linuxSandboxToolsWords = (): string => toolWords(LINUX_SANDBOX_TOOLS.map(tool => tool.package));

/** What a person reads when this Linux computer is missing some of them: which, and the line that installs them. */
export function missingSandboxToolsWords(missing: readonly string[]): string[] {
  return [
    `Toolroll needs ${toolWords(missing)} to run agents in a sandbox on this computer.`,
    `Install ${missing.length === 1 ? "it" : "them"}, then run toolroll again: ${linuxSandboxInstallLine(missing)}`,
  ];
}

/** POSIX shell words. */
export function shellQuote(words: readonly string[]): string {
  return words.map(word => /^[A-Za-z0-9_@%+=:,./-]+$/.test(word) ? word : `'${word.replace(/'/g, `'\\''`)}'`).join(" ");
}

/**
 * The runtime sets a sandboxed command's TMPDIR itself (to $CLAUDE_CODE_TMPDIR of the process asking, or /tmp/claude):
 * the launch's own temp folder when it has one, so it keeps it; otherwise /tmp/claude, made if missing.
 */
export function withRuntimeTemp<T>(temp: string | undefined, make: () => T): T {
  const before = { code: process.env["CLAUDE_CODE_TMPDIR"], old: process.env["CLAUDE_TMPDIR"] };
  delete process.env["CLAUDE_TMPDIR"];
  if (temp !== undefined && temp !== "") process.env["CLAUDE_CODE_TMPDIR"] = temp;
  else { delete process.env["CLAUDE_CODE_TMPDIR"]; try { mkdirSync("/tmp/claude", { recursive: true, mode: 0o700 }); } catch { /* someone else's: writes there fail */ } }
  try { return make(); }
  finally {
    if (before.code === undefined) delete process.env["CLAUDE_CODE_TMPDIR"]; else process.env["CLAUDE_CODE_TMPDIR"] = before.code;
    if (before.old !== undefined) process.env["CLAUDE_TMPDIR"] = before.old;
  }
}

/**
 * Toolroll's own Seatbelt rules, appended to the end of the runtime's profile (Seatbelt takes the last rule that
 * matches). Static: constants here, never made from a launch's data.
 *
 * Terminals: a pseudo-terminal of the launch's own (node-pty, `script`, a test that drives a shell), and no other. The
 * runtime's `allowPty` opens reads and writes on every /dev/ttys device, the operator's own open terminals among them,
 * and its baseline already reads them (a read steals what is typed there). macOS marks a terminal the sandboxed process
 * made with the `com.apple.sandbox.pty` extension (for that terminal only: a device number used again later outside is
 * not covered), so only those are opened by name. A terminal handed down open (a live terminal's own) stays usable.
 */
export const SEATBELT_PTY = [
  "; Toolroll: a pseudo-terminal the launch made itself",
  "(allow pseudo-tty)",
  "(allow file-read* file-write* file-ioctl (literal \"/dev/ptmx\"))",
  "(allow file-read* file-write* file-ioctl (require-all (regex #\"^/dev/ttys[0-9]+$\") (extension \"com.apple.sandbox.pty\")))",
].join("\n");

/** Last in every profile: no other terminal opened by name, and no keystrokes pushed into any terminal (TIOCSTI,
 * _IOW('t', 114, char)), its own controlling terminal included. */
export const SEATBELT_NO_OTHER_TERMINAL = [
  "; Toolroll: no other terminal, and nothing typed into one",
  "(deny file-read-data file-write* (require-all (regex #\"^/dev/ttys[0-9]+$\") (require-not (extension \"com.apple.sandbox.pty\"))))",
  "(deny file-ioctl (ioctl-command 2147578994))",
].join("\n");

/**
 * Last in every launch's profile but a build agent's: the keychain's services. The runtime's
 * baseline lets every sandboxed process ask securityd, so it reads the login keychain's items whose access list lets
 * any program read them (anthropics/sandbox-runtime#755). Build agents keep it (Claude Code signs in from the keychain).
 */
export const SEATBELT_NO_KEYCHAIN = [
  "; Toolroll: no keychain",
  "(deny mach-lookup (with no-report) (global-name \"com.apple.SecurityServer\") (global-name \"com.apple.securityd.xpc\"))",
].join("\n");

/**
 * First after the profile's default deny: a mach service lookup the profile doesn't allow is still denied, unreported.
 * On macOS 26.5 a reported mach-lookup denial now and then never answers: bootstrap_look_up blocks in launchd for good
 * (seen as npm stuck in Node's DNS setup, dns_configuration_copy → com.apple.SystemConfiguration.DNSConfiguration, about
 * 1 launch in 70 under load; never with the report off). Every allow after it still wins, so what is reachable is the
 * same; only the report goes.
 */
export const SEATBELT_QUIET_MACH_DENY = "(deny mach-lookup (with no-report))";

/**
 * Chromium, a project check's launch only: Playwright's default browser (its Chromium headless shell) registers its
 * port rendezvous service as org.chromium.Chromium.MachPortRendezvousServer.<its pid> at start, and its helpers look
 * it up. Exactly that name. Chromium takes the prefix from its bundle id with no switch or variable to change it, and
 * Seatbelt can't tie the pid to the caller, so the residual (another pid's name registered or looked up) is written
 * up in SECURITY.md. Chrome for Testing (`channel: "chromium"`, headed runs) gets nothing: such a check runs Not
 * sandboxed.
 */
export const SEATBELT_CHROMIUM = [
  "; Toolroll: the Chromium headless shell port rendezvous service",
  "(allow mach-register mach-lookup (global-name-regex #\"^org\\.chromium\\.Chromium\\.MachPortRendezvousServer\\.[0-9]+$\"))",
].join("\n");

/** Whether a read deny covers the launch's own terminal devices (/dev/ptmx, /dev/ttys*): then it gets none. */
function deniesTerminals(deny: string): boolean {
  const glob = deny.search(/[*?[]/);
  const path = (glob < 0 ? deny : deny.slice(0, glob)).replace(/\/+$/, "");
  const devices = ["/dev/ptmx", "/dev/ttys0"];
  if (glob >= 0) return devices.some(device => device.startsWith(path));
  return path === "" || path === "/dev" || devices.includes(path) || /^\/dev\/ttys[0-9]*$/.test(path);
}

/** Toolroll's rules for a launch's terms, in order: its own terminal (unless its read denies cover the devices), a
 * check's Chromium service, then the denies that must come last. */
export function seatbeltRulesFor(terms: SrtTerms): string {
  const denied = [...terms.readConfig.denyOnly, ...terms.readConfig.literalDenyOnly ?? []].some(one => deniesTerminals(typeof one === "string" ? one : String(one)));
  return [...denied ? [] : [SEATBELT_PTY], ...terms.browser === true ? [SEATBELT_CHROMIUM] : [], SEATBELT_NO_OTHER_TERMINAL,
    ...terms.keychain === true ? [] : [SEATBELT_NO_KEYCHAIN]].join("\n");
}

const BARE_WORD = /^[A-Za-z0-9_./:@+,-][A-Za-z0-9_./:=@+,-]*$/;

/** The runtime's own quoting (its utils/shell-quote.js): a word bare when nothing in it is special, otherwise in single
 * quotes with a quote inside as '"'"'. */
export function srtQuote(words: readonly string[]): string {
  return words.map(word => word === "" ? "''" : BARE_WORD.test(word) ? word : `'${word.replace(/'/g, `'"'"'`)}'`).join(" ");
}

/** The words of a line srtQuote made, or null for any other line (an operator, a second command, other quoting). */
export function srtWords(line: string): string[] | null {
  const words: string[] = [];
  let at = 0;
  while (at < line.length) {
    let word = "";
    if (line[at] === "'") {
      for (;;) {
        const close = line.indexOf("'", at + 1);
        if (close < 0) return null;
        word += line.slice(at + 1, close);
        at = close + 1;
        if (line.startsWith(`"'"'`, at)) { word += "'"; at += 3; continue; }
        break;
      }
    } else {
      const end = line.indexOf(" ", at);
      word = line.slice(at, end < 0 ? line.length : end);
      if (!BARE_WORD.test(word)) return null;
      at += word.length;
    }
    words.push(word);
    if (at === line.length) break;
    if (line[at] !== " " || at + 1 === line.length) return null;
    at += 1;
  }
  return words.length > 0 && srtQuote(words) === line ? words : null;
}

const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;

/**
 * `command` (the runtime's macOS invocation) with `rules` appended to its profile, made again from its words. The
 * runtime's invocation is exactly `env [-u NAME]… [NAME=value]… /usr/bin/sandbox-exec -p <profile> <shell> -c
 * <command>`, each word quoted its way, and `<command>` is `expected` when given. Any other line (an operator, a word
 * before `env` or after the command, another program) is refused, so the launch doesn't run.
 */
export function withSeatbeltRules(command: string, rules: string, expected?: string): string {
  if (rules.includes("'")) throw new Error("a Seatbelt rule Toolroll adds can't hold a quote");
  const shape = () => new Error("the sandbox runtime's command isn't the shape Toolroll knows");
  const words = srtWords(command);
  if (words === null || words[0] !== "env") throw shape();
  const exec = words.indexOf(SANDBOX_EXEC);
  if (exec < 1 || words.length !== exec + 6 || words[exec + 1] !== "-p" || words[exec + 4] !== "-c") throw shape();
  for (let index = 1; index < exec; index += 1) {
    if (words[index] === "-u") { if (!ENV_NAME.test(words[index + 1] ?? "")) throw shape(); index += 1; continue; }
    const name = words[index]!.split("=", 1)[0]!;
    if (!words[index]!.includes("=") || !ENV_NAME.test(name)) throw shape();
  }
  const profile = words[exec + 2]!;
  if (!profile.startsWith("(version 1)\n(deny default")) throw shape();
  // Where the default deny's line ends (the profile's end when it is the last line).
  const lineEnd = profile.indexOf("\n", "(version 1)\n".length);
  const opening = lineEnd < 0 ? profile.length : lineEnd;
  if (!/^\/[A-Za-z0-9_./-]+$/.test(words[exec + 3]!)) throw shape();
  if (expected !== undefined && words[exec + 5] !== expected) throw shape();
  const quiet = `${profile.slice(0, opening)}\n${SEATBELT_QUIET_MACH_DENY}${profile.slice(opening)}`;
  return srtQuote([...words.slice(0, exec + 2), `${quiet}\n${rules}\n`, ...words.slice(exec + 3)]);
}

/** The runtime's macOS invocation for `file args` run from `cwd`: a command line for /bin/sh. */
export function srtMacosCommand(file: string, args: readonly string[], terms: SrtTerms, cwd: string = process.cwd(), temp?: string): string {
  const network = terms.network;
  const params = {
    command: shellQuote([file, ...args]),
    needsNetworkRestriction: network.kind === "proxy",
    ...(network.kind === "proxy" ? {
      httpProxyPort: network.httpPort,
      ...(network.socksPort === undefined ? {} : { socksProxyPort: network.socksPort }),
      ...(network.token === undefined ? {} : { proxyAuthToken: network.token }),
      allowLocalBinding: network.localServices,
      ...(network.unixSockets.length === 0 ? {} : { allowUnixSockets: network.unixSockets }),
    } : {}),
    ...(terms.allowMachLookup.length === 0 ? {} : { allowMachLookup: terms.allowMachLookup }),
    readConfig: terms.readConfig,
    writeConfig: terms.writeConfig,
  };
  // The runtime anchors its mandatory write denies at this process's working folder: the launch's, for this call.
  const before = process.cwd();
  process.chdir(cwd);
  let command: string;
  try { command = withRuntimeTemp(temp, () => wrapCommandWithSandboxMacOS(params)); }
  finally { process.chdir(before); }
  return withSeatbeltRules(command, seatbeltRulesFor(terms), params.command);
}

/**
 * macOS: what every sandboxed launch runs first, outside the sandbox, before it execs the runtime's command: a session of
 * its own (setsid, syscall 147), so no terminal of whoever started Toolroll is its controlling terminal to reach. A
 * launch that is a session leader already (a live terminal's program, its own terminal made for it) keeps that one; any
 * other that still has a controlling terminal (getsid, syscall 310) is refused. Perl with -t reads neither PERL5OPT nor
 * PERL5LIB, and -X keeps its taint warnings off the launch's output.
 */
export const DETACH: readonly string[] = ["-t", "-X", "-e",
  'syscall(147) != -1 or syscall(310, 0) == $$ or !open(my $t, "<", "/dev/tty") or die "toolroll: the sandboxed launch kept a terminal\\n"; exec { $ARGV[0] } @ARGV; die "toolroll: the sandbox could not start: $!\\n";'];

/** The Linux helper (sandbox-launch.ts) and the environment variable its launch is handed in. */
export const SANDBOX_LAUNCH_SPEC = "TOOLROLL_SANDBOX_LAUNCH";
export const sandboxLaunchHelper = (): string => {
  const beside = fileURLToPath(new URL("./sandbox-launch.js", import.meta.url));
  // Run from the sources (the test suite), the built helper is the package's own.
  return existsSync(beside) ? beside : fileURLToPath(new URL("../dist/sandbox-launch.js", import.meta.url));
};

/** What the Linux helper is given: the command, where it runs, the terms, and the sandbox's own programs by their
 * checked paths (sandbox-tools.ts), which the helper checks again in full before it uses them. */
export type SandboxLaunchSpec = { file: string; args: string[]; cwd: string; terms: SrtTerms; tools: LinuxSandboxTools; temp?: string };

/**
 * `file args` inside the runtime's sandbox, as a spawn: on macOS `/bin/sh -c <its command>` in a session of its own
 * (DETACH); on Linux the helper,
 * handed the launch in its environment (never its arguments, which other users can list).
 */
export function srtSpawn(file: string, args: readonly string[], terms: SrtTerms, cwd: string = process.cwd(), temp?: string, platform: NodeJS.Platform = process.platform, tools: (exclusions: ToolExclusions) => LinuxSandboxToolsVerdict = linuxSandboxTools): { file: string; args: string[]; env: Record<string, string> } {
  if (platform === "darwin") {
    const command = srtMacosCommand(file, args, terms, cwd, temp);
    if (!command.includes(SANDBOX_EXEC)) throw new Error("the sandbox runtime returned the command unsandboxed");
    return { file: "/usr/bin/perl", args: [...DETACH, "/bin/sh", "-c", command], env: {} };
  }
  // The sandbox's programs by trusted path, none inside this launch's projects, worktrees or state: else nothing starts.
  const resolved = tools(sandboxToolExclusions(terms, cwd));
  if (!resolved.ok) throw new Error(resolved.why);
  const spec: SandboxLaunchSpec = { file, args: [...args], cwd, terms, tools: resolved.tools, ...(temp === undefined ? {} : { temp }) };
  return { file: process.execPath, args: [sandboxLaunchHelper()], env: { [SANDBOX_LAUNCH_SPEC]: JSON.stringify(spec) } };
}
